import { EntityTfError } from "../../engine/entity.js";
import { expr } from "../../engine/tf/index.js";
import { CATEGORY_ORG_BAG } from "../org/category.js";
import { categoryIdExpr, missingCategoryDiagnostic } from "../org/category-ref.js";
import { CLOUD_LINK_ORG_BAG } from "../org/cloud-link.js";
import { TASK_RESOURCE_TYPE } from "./module.js";
export function taskToTf(entity, ctx) {
    if (entity.kind !== "task")
        throw new EntityTfError(`taskToTf expects task; got ${entity.kind}`);
    const p = entity.payload;
    if (p === null || !p.name || !p.handle || !p.namespace)
        throw new EntityTfError(`task ${entity.refName}: name, handle, and namespace are required`);
    const attrs = { name: p.name, handle: p.handle, namespace: p.namespace };
    const categoryRefName = p.category?.refName;
    const category = categoryRefName ? ctx.orgRefs.byTsLabel(CATEGORY_ORG_BAG, categoryRefName) : undefined;
    if (category === undefined)
        ctx.diagnostics.push(`task ${JSON.stringify(p.name)}: ${missingCategoryDiagnostic(categoryRefName ?? "")}`);
    else
        attrs["category_id"] = categoryIdExpr(category);
    if (p.cloudLink?.refName) {
        const link = ctx.orgRefs.byTsLabel(CLOUD_LINK_ORG_BAG, p.cloudLink.refName);
        if (link === undefined)
            ctx.diagnostics.push(`task ${JSON.stringify(p.name)}: cloud link ${JSON.stringify(p.cloudLink.refName)} is not in the org catalog`);
        else
            attrs["cloud_link_id"] = expr.dataAttr("elementum_cloudlink", link.tfLabel, ["id"]);
    }
    if (p.description !== undefined)
        attrs["description"] = p.description;
    if (p.icon !== undefined)
        attrs["icon"] = p.icon;
    if (p.color !== undefined)
        attrs["color"] = p.color;
    if (p.commentsEnabled !== undefined)
        attrs["comments_enabled"] = p.commentsEnabled;
    if (p.titleField?.name !== undefined)
        attrs["title_field_name"] = p.titleField.name;
    if (p.titleField?.description !== undefined)
        attrs["title_field_description"] = p.titleField.description;
    if (p.idField?.name !== undefined)
        attrs["id_field_name"] = p.idField.name;
    if (p.idField?.description !== undefined)
        attrs["id_field_description"] = p.idField.description;
    if (p.statusField?.name !== undefined)
        attrs["status_field_name"] = p.statusField.name;
    if (p.statusField?.description !== undefined)
        attrs["status_field_description"] = p.statusField.description;
    if (p.statusField?.options !== undefined)
        attrs["status_options"] = p.statusField.options.map((option) => ({ label: option.label ?? "", ...(option.color !== undefined && { color: option.color }), tags: [...(option.tags ?? [])] }));
    return { blocks: [{ kind: "resource", type: TASK_RESOURCE_TYPE, label: p.namespace, attrs }] };
}
